#!/bin/bash
# Build "__NAME__.app" (__NAME_ZH__) into ./build.  Generated by qiaomu-macos-dev.
# Signed with Developer ID + hardened runtime so dev builds and the installed app share ONE
# Accessibility/TCC grant (ad-hoc signatures change every build and silently drop permissions).
# RELEASE=1: universal binary (arm64 + x86_64) and a secure timestamp (required for notarization).
set -euo pipefail
cd "$(dirname "$0")"
NAME="__NAME__"
NAME_ZH="__NAME_ZH__"
BUNDLE_ID="__BUNDLE_ID__"
REPO="__REPO__"
VERSION=$(cat VERSION)
BUILD_NUMBER=$(date +%Y%m%d%H%M)                       # monotonic: Sparkle compares CFBundleVersion

ARCHS=(); if [ "${RELEASE:-0}" = "1" ]; then ARCHS=(--arch arm64 --arch x86_64); fi
swift build -c release ${ARCHS[@]+"${ARCHS[@]}"}
BIN=$(swift build -c release ${ARCHS[@]+"${ARCHS[@]}"} --show-bin-path)
APP="build/$NAME.app"
rm -rf "$APP"; mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources" "$APP/Contents/Frameworks"
cp "$BIN/$NAME" "$APP/Contents/MacOS/$NAME"
# Resource folders are copied only when present (fonts, icons, sounds, About QR codes…).
for d in Fonts Icons Sounds About; do if [ -d "Resources/$d" ]; then cp -R "Resources/$d" "$APP/Contents/Resources/$d"; fi; done
if [ -f THIRD_PARTY_NOTICES.md ]; then cp THIRD_PARTY_NOTICES.md "$APP/Contents/Resources/"; fi
for b in "$BIN"/*.bundle; do if [ -e "$b" ]; then cp -R "$b" "$APP/Contents/Resources/"; fi; done

# Sparkle: embed the framework and let the binary find it.
ditto "$BIN/Sparkle.framework" "$APP/Contents/Frameworks/Sparkle.framework"
if ! otool -l "$APP/Contents/MacOS/$NAME" | grep -q "@executable_path/../Frameworks"; then
  install_name_tool -add_rpath "@executable_path/../Frameworks" "$APP/Contents/MacOS/$NAME"
fi

# Icon Composer icon → Assets.car (macOS 26+ Liquid Glass) + AppIcon.icns (older systems).
compile_icon() {
  xcrun actool "$PWD/Resources/AppIcon.icon" --compile "$PWD/$APP/Contents/Resources" --platform macosx \
    --minimum-deployment-target 13.0 --app-icon AppIcon --target-device mac \
    --output-partial-info-plist "$PWD/build/icon-partial.plist" > build/actool.log 2>&1
}
# actool reuses a background helper (ibtoold); if this folder was deleted/re-cloned, the helper's working
# directory is stale ("currentDirectoryPath is unexpectedly nil"). Restart it and retry once.
if ! compile_icon; then
  pkill -x ibtoold 2>/dev/null || true; pkill -f AssetCatalogAgent 2>/dev/null || true; sleep 1
  compile_icon || { cat build/actool.log; exit 1; }
fi

SPARKLE_KEY=$(cat Resources/sparkle-public-key.txt 2>/dev/null || echo "")
cat > "$APP/Contents/Info.plist" <<PL
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
<key>CFBundleName</key><string>$NAME</string>
<key>CFBundleDisplayName</key><string>$NAME</string>
<key>LSHasLocalizedDisplayName</key><true/>
<key>CFBundleLocalizations</key><array><string>zh-Hans</string><string>en</string></array>
<key>CFBundleIdentifier</key><string>$BUNDLE_ID</string>
<key>CFBundleExecutable</key><string>$NAME</string>
<key>CFBundleIconFile</key><string>AppIcon</string>
<key>CFBundleIconName</key><string>AppIcon</string>
<key>CFBundleVersion</key><string>$BUILD_NUMBER</string>
<key>CFBundleShortVersionString</key><string>$VERSION</string>
<key>CFBundlePackageType</key><string>APPL</string>
<key>CFBundleDevelopmentRegion</key><string>zh-Hans</string>
<key>LSApplicationCategoryType</key><string>public.app-category.productivity</string>
<key>LSMinimumSystemVersion</key><string>13.0</string>
<key>LSUIElement</key><__MENUBAR__/>
<key>NSHighResolutionCapable</key><true/>
<key>NSHumanReadableCopyright</key><string>© $(date +%Y) 向阳乔木</string>
<key>SUFeedURL</key><string>https://github.com/$REPO/releases/latest/download/appcast.xml</string>
<key>SUPublicEDKey</key><string>$SPARKLE_KEY</string>
<key>SUEnableAutomaticChecks</key><true/>
</dict></plist>
PL

# Localized display name: Finder shows NAME_ZH on Chinese systems. The bundle file name must equal CFBundleName.
mkdir -p "$APP/Contents/Resources/zh-Hans.lproj" "$APP/Contents/Resources/en.lproj"
printf '"CFBundleName" = "%s";\n"CFBundleDisplayName" = "%s";\n' "$NAME_ZH" "$NAME_ZH" > "$APP/Contents/Resources/zh-Hans.lproj/InfoPlist.strings"
printf '"CFBundleName" = "%s";\n"CFBundleDisplayName" = "%s";\n' "$NAME" "$NAME" > "$APP/Contents/Resources/en.lproj/InfoPlist.strings"

IDENTITY=$(security find-identity -v -p codesigning 2>/dev/null | grep -m1 "Developer ID Application" | sed -E 's/.*"(.*)"/\1/' || true)
if [ -z "$IDENTITY" ]; then
  IDENTITY=$(security find-identity -v -p codesigning 2>/dev/null | grep -m1 "Apple Development" | sed -E 's/.*"(.*)"/\1/' || true)
fi
TS="--timestamp=none"; if [ "${RELEASE:-0}" = "1" ]; then TS="--timestamp"; fi
# Nested code first (Sparkle's documented Developer ID order), never --deep.
SPK="$APP/Contents/Frameworks/Sparkle.framework/Versions/B"
for item in "$SPK/XPCServices/Installer.xpc" "$SPK/XPCServices/Downloader.xpc" "$SPK/Autoupdate" "$SPK/Updater.app" \
            "$APP/Contents/Frameworks/Sparkle.framework"; do
  if [ -e "$item" ]; then codesign --force --options runtime $TS --preserve-metadata=entitlements --sign "${IDENTITY:--}" "$item"; fi
done
codesign --force --options runtime $TS --entitlements "Resources/$NAME.entitlements" --sign "${IDENTITY:--}" "$APP"
echo "Built: $APP ($VERSION, signed by ${IDENTITY:-ad-hoc})"
